<?php
declare(strict_types=1); namespace App\Http\Controllers\ParentPortal; use App\Http\Controllers\Controller; use App\Models\StudentAttendance; use App\Services\Academic\LessonScheduleService; use App\Services\ParentPortal\GuardianAccessService; use Illuminate\Http\Request; use Illuminate\View\View;
class DashboardController extends Controller { public function __invoke(Request $request,GuardianAccessService $access,LessonScheduleService $lessons):View{$guardian=$access->guardian($request->user());$children=$guardian->students()->with('activeClassroomMembership.classroom.academicYear')->get();$student=$children->firstWhere('id',(int)$request->query('student'))??$children->first();$schedule=['current'=>null,'next'=>null,'timeline'=>collect()];$attendance=null;if($student){$student=$access->student($request->user(),$student->id);$membership=$student->activeClassroomMembership;if($membership){$semester=\App\Models\Semester::where('academic_year_id',$membership->classroom->academic_year_id)->where('is_active',true)->first();if($semester)$schedule=$lessons->currentAndNext($membership->classroom_id,$semester->id);$attendance=StudentAttendance::where('student_id',$student->id)->whereDate('attendance_date',now('Asia/Jakarta')->toDateString())->first();}}return view('parent.dashboard',compact('guardian','children','student','schedule','attendance'));} }
